  ('cpiuris2025::d95879f0a5266bff4b6f1714f366401b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Inconstitucionalidade da Emenda Constitucional nº 45/2019', '## Inconstitucionalidade da Emenda Constitucional nº 45/2019

