  ('cpiuris2025::215988a1ed8227d5f8a7a2ca165f64fa', 'doutrina', 'cp_iuris', 'Direitos Humanos — Dever Solidário do Estado e da Família na Prestação do Ensino Fundamental', '## Dever Solidário do Estado e da Família na Prestação do Ensino Fundamental

