  ('cpiuris2025::3afcdfc2eb3a30e3222305c0df7cd431', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos Humanos', '## Declaração Universal dos Direitos Humanos

