  ('cpiuris2025::01e8ddeda748fc117d1195a39473136e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento e proteção dos direitos humanos', '## Reconhecimento e proteção dos direitos humanos

