  ('cpiuris2025::fa4c02c234a6524efc4d42a78dd576d0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Protocolo de San Salvador e outros instrumentos internacionais', '## Protocolo de San Salvador e outros instrumentos internacionais

